---
export interface Props {
	title: string;
	description?: string;
	image?: string;
}

const { title, description = "Discover the best open source alternatives to popular proprietary software", image = "/og-image.jpg" } = Astro.props;
---

<!doctype html>
<html lang="en">
	<head>
		<meta charset="UTF-8" />
		<meta name="description" content={description} />
		<meta name="viewport" content="width=device-width" />
		<link rel="icon" type="image/svg+xml" href="/favicon.svg" />
		<meta name="generator" content={Astro.generator} />
		<title>{title}</title>
